function extractJSON(s) {
  if (!s) return null;
  let t = String(s).trim();
  const m = t.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (m) t = m[1].trim();
  const start = t.indexOf('{');
  if (start >= 0) {
    let depth = 0, inStr = false, esc = false;
    for (let i = start; i < t.length; i++) {
      const c = t[i];
      if (inStr) { if (esc) esc = false; else if (c === '\\') esc = true; else if (c === '"') inStr = false; continue; }
      if (c === '"') inStr = true;
      else if (c === '{') depth++;
      else if (c === '}') { depth--; if (depth === 0) { try { return JSON.parse(t.slice(start, i + 1)); } catch (e) { return null; } } }
    }
  }
  try { return JSON.parse(t); } catch (e) { return null; }
}

function clean(s) {
  if (s === null || s === undefined) return '';
  let t = String(s);
  const tr = t.trim();
  if ((tr.startsWith('{') && tr.endsWith('}')) || (tr.startsWith('[') && tr.endsWith(']'))) {
    try {
      const j = JSON.parse(tr);
      const cand = (j && typeof j === 'object') ? (j.full_text || j.script || j.text || j.content || j.answer || '') : (j === null ? '' : String(j));
      if (String(cand).trim() !== '') t = String(cand);
    } catch (e) {}
  } else if (tr.length >= 2 && tr[0] === '"' && tr[tr.length - 1] === '"') {
    try { const j = JSON.parse(tr); if (typeof j === 'string' && j.trim() !== '') t = j; } catch (e) {}
  }
  t = t.replace(/```(?:json|text)?\s*([\s\S]*?)```/gi, '$1');
  t = t.replace(/\[([^\]]*)\]\([^)]*\)/g, '$1');
  t = t.replace(/\*\*([^*]+)\*\*/g, '$1');
  t = t.replace(/\*([^*]+)\*/g, '$1');
  t = t.replace(/__([^_]+)__/g, '$1');
  t = t.replace(/`([^`]*)`/g, '$1');
  t = t.replace(/^#{1,6}\s*/gm, '');
  const keep = [];
  for (const ln of t.split('\n')) {
    const s2 = ln.trim();
    if (s2 === '') continue;
    if (/^(note|tags?|so i should|верни|начни|только|пример|вот|json|сценарий|script)\s*[:,\-–—]/i.test(s2)) continue;
    if (/^(вот\s+(сценарий|текст)|ниже\s+сценарий|сгенерированный\s+сценарий)/i.test(s2)) continue;
    keep.push(s2);
  }
  t = keep.join('\n');
  t = t.replace(/^\s*(?:Хук|HOOK|Hook|Основная часть|BODY|Body|Вывод и призыв|Вывод|CTA|Cta|Заключение|Призыв|Концовка|Вступление)\s*[:—–\-]\s*/gim, '');
  t = t.replace(/\s+(?:Хук|Основная часть|Вывод и призыв|Вывод|Заключение|Призыв|Концовка)\s*[:—–\-]\s*/gi, ' ');
  t = t.replace(/\s+(?:HOOK|BODY|CTA)\s*[:—–\-]\s*/gi, ' ');
  return t.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}

